package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.CRC32C;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalUtf8BomTest {

	@TempDir
	Path directory;

	@Test
	void acceptsUtf8BomInHeaderAndMintedFrame() throws Exception {
		try (OutputStream output = Files.newOutputStream(directory.resolve("wal-1.v1"))) {
			writeFrame(output, "\ufeff{\"t\":\"V\",\"segment\":1,\"firstId\":1}");
			writeFrame(output, "\ufeff{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"B\",\"lex\":\"node\"}");
		}
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(directory)
				.storeUuid("utf8-bom")
				.build();
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			ValueStoreWalReader.ScanResult scan = reader.scan();
			assertThat(scan.records()).extracting(ValueStoreWalRecord::lexical).containsExactly("node");
			assertThat(scan.lastValidLsn()).isEqualTo(1);
			assertThat(scan.complete()).isTrue();
		}
	}

	private static void writeFrame(OutputStream output, String json) throws Exception {
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		CRC32C crc = new CRC32C();
		crc.update(bytes, 0, bytes.length);
		writeIntLE(output, bytes.length);
		output.write(bytes);
		writeIntLE(output, (int) crc.getValue());
	}

	private static void writeIntLE(OutputStream output, int value) throws Exception {
		output.write(value);
		output.write(value >>> 8);
		output.write(value >>> 16);
		output.write(value >>> 24);
	}
}
